package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"

	"github.com/shopspring/decimal"
)

type SchedRec struct { // 01 SCHED-REC, 16 bytes
	ScAcct string // PIC X(4) @0 len=4
	ScPrin decimal.Decimal // PIC 9(5)V99 @4 len=7
	ScRate decimal.Decimal // PIC 9(2)V99 @11 len=4
	ScYears int64 // PIC 9(1) @15 len=1
}

// Standalone working-storage items (VALUE shown after '=')
var WsEofFlag string // PIC X len=1 = "N"
var WsBal decimal.Decimal // PIC 9(8)V99 len=10 = 0
var WsYear int64 // PIC 99 len=2 = 0
var WsCount int64 // PIC 99 len=2 = 0
var WsBalEd string // PIC ZZ,ZZZ,ZZ9.99 len=13

var curRec SchedRec

var schedLines []string
var schedIdx int

func parsePic9v99(s string, intDigits int, scale int32) decimal.Decimal {
	s = strings.TrimSpace(s)
	if s == "" {
		return decimal.NewFromInt(0)
	}
	// digits only expected
	neg := false
	if strings.HasPrefix(s, "-") {
		neg = true
		s = s[1:]
	} else if strings.HasPrefix(s, "+") {
		s = s[1:]
	}
	// keep only digits
	digits := ""
	for _, ch := range s {
		if ch >= '0' && ch <= '9' {
			digits += string(ch)
		}
	}
	if digits == "" {
		return decimal.NewFromInt(0)
	}
	// strip high-order digits that don't fit? input fits
	n := int64(0)
	for _, ch := range digits {
		n = n*10 + int64(ch-'0')
	}
	d := decimal.New(n, -scale)
	if neg {
		d = d.Neg()
	}
	return d
}

func parsePic9(s string) int64 {
	s = strings.TrimSpace(s)
	if s == "" {
		return 0
	}
	var n int64
	for _, ch := range s {
		if ch >= '0' && ch <= '9' {
			n = n*10 + int64(ch-'0')
		}
	}
	return n
}

func padRight(s string, n int) string {
	if len(s) >= n {
		return s[:n]
	}
	return s + strings.Repeat(" ", n-len(s))
}

func fitBal(v decimal.Decimal) decimal.Decimal {
	// v already rounded/truncated to scale 2; keep low-order 10 digits (8+2)
	scaled := v.Shift(2).Truncate(0)
	mod := decimal.NewFromInt(10000000000)
	// handle sign: keep sign, mod magnitude
	neg := scaled.IsNegative()
	abs := scaled.Abs()
	q := abs.Mod(mod)
	if neg && !q.IsZero() {
		q = q.Neg()
	}
	return q.Shift(-2)
}

func formatBalEd(v decimal.Decimal) string {
	neg := v.IsNegative()
	abs := v.Abs().Truncate(2)
	scaled := abs.Shift(2).Truncate(0)
	lv := scaled.IntPart() % 10000000000
	if lv < 0 {
		lv = -lv
	}
	intPart := lv / 100
	fracPart := lv % 100
	intStr := fmt.Sprintf("%08d", intPart)
	fracStr := fmt.Sprintf("%02d", fracPart)
	firstNZ := 7
	for i := 0; i < 8; i++ {
		if intStr[i] != '0' {
			firstNZ = i
			break
		}
	}
	var out []byte
	for i := 0; i < 8; i++ {
		if i == 2 || i == 5 {
			if i <= firstNZ {
				out = append(out, ' ')
			} else {
				out = append(out, ',')
			}
		}
		if i < firstNZ {
			out = append(out, ' ')
		} else {
			out = append(out, intStr[i])
		}
	}
	s := string(out) + "." + fracStr
	if neg {
		// place minus in leftmost space if possible (COBOL-like)
		b := []byte(s)
		for i := 0; i < len(b); i++ {
			if b[i] == ' ' {
				continue
			}
			if i > 0 {
				b[i-1] = '-'
			} else {
				// no room; drop high order (already dropped)
			}
			break
		}
		// all spaces case (should not happen for neg zero)
		s = string(b)
	}
	return s
}

func MainPara() {
	f, err := os.Open("input.dat")
	if err != nil {
		// empty input behaves as EOF
		schedLines = nil
	} else {
		sc := bufio.NewScanner(f)
		// allow long lines
		sc.Buffer(make([]byte, 1024*1024), 1024*1024)
		for sc.Scan() {
			line := sc.Text()
			// strip trailing \r if CRLF (Scanner strips \n, leaves \r)
			line = strings.TrimSuffix(line, "\r")
			schedLines = append(schedLines, line)
		}
		f.Close()
	}
	schedIdx = 0
	ReadPara()
	for !(WsEofFlag == "Y") {
		ProcessPara()
	}
	// CLOSE SCHED-FILE (no-op)
	fmt.Printf("SCHEDULES: %02d\n", WsCount)
}

func ReadPara() {
	if schedIdx >= len(schedLines) {
		WsEofFlag = "Y"
		return
	}
	line := schedLines[schedIdx]
	schedIdx++
	line = padRight(line, 16)
	acct := line[0:4]
	prinStr := line[4:11]
	rateStr := line[11:15]
	yearsStr := line[15:16]
	curRec.ScAcct = acct
	curRec.ScPrin = parsePic9v99(prinStr, 5, 2)
	curRec.ScRate = parsePic9v99(rateStr, 2, 2)
	curRec.ScYears = parsePic9(yearsStr)
}

func ProcessPara() {
	WsBal = fitBal(curRec.ScPrin.Truncate(2))
	WsYear = 1
	for !(WsYear > curRec.ScYears) {
		factor := curRec.ScRate.Shift(-2).Add(decimal.NewFromInt(1))
		prod := WsBal.Mul(factor)
		rounded := prod.Round(2)
		WsBal = fitBal(rounded)
		WsBalEd = formatBalEd(WsBal)
		fmt.Printf("%s Y%02d %s\n", curRec.ScAcct, WsYear, WsBalEd)
		WsYear++
		// keep PIC 99 range (low-order)
		WsYear = WsYear % 100
		// Note: COBOL VARYING does not wrap in practice for small values;
		// the modulo above only matters on overflow. To avoid breaking
		// the loop logic when wrapping, keep raw value if small.
		// Since years < 10, overflow never happens here.
	}
	WsBalEd = formatBalEd(WsBal)
	fmt.Printf("%s FINAL %s\n", curRec.ScAcct, WsBalEd)
	WsCount = (WsCount + 1) % 100
	ReadPara()
}

func main() {
	WsEofFlag = "N"
	WsBal = decimal.NewFromInt(0)
	WsYear = 0
	WsCount = 0
	WsBalEd = formatBalEd(decimal.NewFromInt(0))
	MainPara()
}
